"""Intent tests for risk.summary_stats (RISK-04, TC-07): annualized return, vol, Sharpe, last vol."""

from __future__ import annotations

import math
import statistics
from typing import Any

import pytest

from risk.summary import TickerSummary, summary_stats
from risk.types import Returns, VolSeries


def _returns(payload: dict[str, Any]) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _vol(payload: dict[str, Any]) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _one_ticker_vol(values: list[float], vols: list[float | None]) -> VolSeries:
    dates = tuple(f"2024-02-{day:02d}" for day in range(2, len(values) + 2))
    returns = Returns(base_date="2024-02-01", dates=dates, tickers=("X",), values={"X": tuple(values)})
    return VolSeries(returns=returns, window=2, annualized=True, values={"X": tuple(vols)})


@pytest.mark.intent
def test_tc07_summary_per_ticker(golden):
    given_input, expected = golden("risk", "TC-07")
    result = summary_stats(_vol(given_input["vol"]))
    tol = expected["tol"]
    assert [s.ticker for s in result] == [row["ticker"] for row in expected["summary"]]
    for got, want in zip(result, expected["summary"], strict=True):
        assert isinstance(got, TickerSummary)
        assert got.ann_return == pytest.approx(want["ann_return"], abs=tol, rel=0)
        assert got.ann_vol == pytest.approx(want["ann_vol"], abs=tol, rel=0)
        assert got.sharpe == pytest.approx(want["sharpe"], abs=tol, rel=0)
        assert got.last_vol == pytest.approx(want["last_vol"], abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    given_input, expected = golden("risk", "TC-07")
    result = {s.ticker: s for s in summary_stats(_vol(given_input["vol"]))}
    want = {row["ticker"]: row for row in expected["summary"]}
    assert result["Y"].ann_vol == pytest.approx(want["Y"]["ann_vol"], abs=expected["tol"], rel=0)
    assert result["Y"].sharpe == want["Y"]["sharpe"]
    assert math.isfinite(result["Y"].sharpe)


@pytest.mark.intent
def test_tc07_last_vol_skips_trailing_none(golden):
    given_input, expected = golden("risk", "TC-07")
    assert given_input["vol"]["values"]["X"][-1] is None
    result = {s.ticker: s for s in summary_stats(_vol(given_input["vol"]))}
    want = {row["ticker"]: row for row in expected["summary"]}
    assert result["X"].last_vol == pytest.approx(want["X"]["last_vol"], abs=expected["tol"], rel=0)


@pytest.mark.intent
def test_contract_sample_matches_the_formulas(contract_sample):
    vol = _vol({**contract_sample("risk.VolSeries")})
    result = summary_stats(vol)
    assert tuple(s.ticker for s in result) == vol.returns.tickers
    for got in result:
        series = vol.returns.values[got.ticker]
        ann_return = 252 * statistics.fmean(series)
        ann_vol = math.sqrt(252) * statistics.stdev(series)
        assert got.ann_return == pytest.approx(ann_return, abs=1e-9, rel=0)
        assert got.ann_vol == pytest.approx(ann_vol, abs=1e-9, rel=0)
        assert got.sharpe == pytest.approx(ann_return / ann_vol, abs=1e-9, rel=0)
        assert got.last_vol == pytest.approx(vol.values[got.ticker][-1], abs=1e-12, rel=0)


@pytest.mark.intent
def test_periods_per_year_scales_return_and_vol():
    values = [0.01, -0.02, 0.03]
    vol = _one_ticker_vol(values, [None, None, 0.3])
    (result,) = summary_stats(vol, periods_per_year=12)
    ann_return = 12 * statistics.fmean(values)
    ann_vol = math.sqrt(12) * statistics.stdev(values)
    assert result.ann_return == pytest.approx(ann_return, abs=1e-12, rel=0)
    assert result.ann_vol == pytest.approx(ann_vol, abs=1e-12, rel=0)
    assert result.sharpe == pytest.approx(ann_return / ann_vol, abs=1e-12, rel=0)


@pytest.mark.intent
def test_volatility_uses_the_sample_standard_deviation():
    values = [0.01, -0.01]
    vol = _one_ticker_vol(values, [None, None])
    (result,) = summary_stats(vol)
    # sample stdev of (0.01, -0.01) is sqrt(2) * 0.01; population stdev would be 0.01
    assert result.ann_vol == pytest.approx(math.sqrt(252) * math.sqrt(2) * 0.01, abs=1e-12, rel=0)
    assert result.ann_return == pytest.approx(0.0, abs=1e-12)


@pytest.mark.intent
def test_no_rolling_value_gives_none_last_vol():
    vol = _one_ticker_vol([0.01, -0.01], [None, None])
    (result,) = summary_stats(vol)
    assert result.last_vol is None


@pytest.mark.intent
def test_fewer_than_two_returns_raises():
    vol = _one_ticker_vol([0.01], [None])
    with pytest.raises(ValueError, match=r"(?i)two|2|returns?"):
        summary_stats(vol)

